  9	public class DocumentService {
 10	
 11	    public Document generateDocument(Reservation reservation, Room room) {
 12	        String text;
 13	        String title;
 14	
 15	        if (reservation.getGuestCpf() != null) {
 16	            title = "Comprovante de reserva";
 17	            text = generateComprovante(reservation, room);
 18	        } else if (reservation.getCompanyCnpj() != null) {
 19	            title = "Fatura de hospedagem";
 20	            text = generateFatura(reservation, room);
 21	        } else {
 22	            title = "Booking receipt";
 23	            text = generateBookingReceipt(reservation, room);
 24	        }
 25	
 26	        return new Document(
 27	            title,
 28	            reservation.getId(),
 29	            reservation.getGuestName(),
 30	            reservation.getGuestCpf(),
 31	            reservation.getCompanyCnpj(),
 32	            reservation.getCompanyName(),
 33	            reservation.getGuestPassport(),
 34	            reservation.getGuestCountry(),
 35	            room.getNumber(),
 36	            room.getType(),
 37	            reservation.getCheckIn(),
 38	            reservation.getCheckOut(),
 39	            reservation.getNights(),
 40	            reservation.getSubtotal(),
 41	            reservation.getDiscount(),
 42	            reservation.getTotal(),
 43	            text
 44	        );
 45	    }
 46	
 47	    private String generateComprovante(Reservation reservation, Room room) {
 48	        StringBuilder sb = new StringBuilder();
 49	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
 50	        sb.append("Hóspede: ").append(reservation.getGuestName())
 51	          .append(" (CPF ").append(CpfFormatter.format(reservation.getGuestCpf())).append(")\n");
 52	        sb.append("Quarto: ").append(room.getNumber()).append(" (").append(room.getType()).append(")\n");
 53	        sb.append("Entrada: ").append(DateFormatter.formatPtBr(reservation.getCheckIn()))
 54	          .append(" | Saída: ").append(DateFormatter.formatPtBr(reservation.getCheckOut()))
 55	          .append(" | ").append(reservation.getNights())
 56	          .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
 57	        sb.append("Diárias: ").append(MoneyFormatter.formatPtBr(reservation.getSubtotal())).append("\n");
 58	
 59	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 60	            sb.append("Desconto: ").append(MoneyFormatter.formatPtBr(reservation.getDiscount())).append("\n");
 61	        }
 62	
 63	        sb.append("Total: ").append(MoneyFormatter.formatPtBr(reservation.getTotal()));
 64	
 65	        return sb.toString();
 66	    }
 67	
 68	    private String generateFatura(Reservation reservation, Room room) {
 69	        StringBuilder sb = new StringBuilder();
 70	        sb.append("Fatura de hospedagem nº ").append(reservation.getId()).append("\n");
 71	        sb.append("Empresa: ").append(reservation.getCompanyName())
 72	          .append(" (CNPJ ").append(CnpjFormatter.format(reservation.getCompanyCnpj())).append(")\n");
 73	        sb.append("Hóspede: ").append(reservation.getGuestName()).append("\n");
 74	        sb.append("Quarto: ").append(room.getNumber()).append(" (").append(room.getType()).append(")\n");
 75	        sb.append("Entrada: ").append(DateFormatter.formatPtBr(reservation.getCheckIn()))
 76	          .append(" | Saída: ").append(DateFormatter.formatPtBr(reservation.getCheckOut()))
 77	          .append(" | ").append(reservation.getNights())
 78	          .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
 79	        sb.append("Diárias: ").append(MoneyFormatter.formatPtBr(reservation.getSubtotal())).append("\n");
 80	
 81	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 82	            sb.append("Desconto: ").append(MoneyFormatter.formatPtBr(reservation.getDiscount())).append("\n");
 83	        }
 84	
 85	        sb.append("Total: ").append(MoneyFormatter.formatPtBr(reservation.getTotal())).append("\n");
 86	        sb.append("ISS retido (5%): ").append(MoneyFormatter.formatPtBr(PriceCalculator.calculateIss(reservation.getTotal())));
 87	
 88	        return sb.toString();
 89	    }
 90	
 91	    private String generateBookingReceipt(Reservation reservation, Room room) {
 92	        StringBuilder sb = new StringBuilder();
 93	        sb.append("Booking receipt no. ").append(reservation.getId()).append("\n");
 94	        sb.append("Guest: ").append(reservation.getGuestName())
 95	          .append(" (passport ").append(reservation.getGuestPassport())
 96	          .append(", ").append(reservation.getGuestCountry()).append(")\n");
 97	        sb.append("Room: ").append(room.getNumber()).append(" (").append(room.getType()).append(")\n");
 98	        sb.append("Check-in: ").append(DateFormatter.formatEn(reservation.getCheckIn()))
 99	          .append(" | Check-out: ").append(DateFormatter.formatEn(reservation.getCheckOut()))
100	          .append(" | ").append(reservation.getNights())
101	          .append(reservation.getNights() == 1 ? " night" : " nights").append("\n");
102	        sb.append("Nights: ").append(MoneyFormatter.formatEn(reservation.getSubtotal())).append("\n");
103	
104	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
105	            sb.append("Discount: ").append(MoneyFormatter.formatEn(reservation.getDiscount())).append("\n");
106	        }
107	
108	        sb.append("Total: ").append(MoneyFormatter.formatEn(reservation.getTotal()));
109	
110	        return sb.toString();
111	    }
112	}
