381	package br.com.pousada.service;
382	
383	import br.com.pousada.model.*;
384	import br.com.pousada.util.PriceCalculator;
385	import java.math.BigDecimal;
386	import java.time.LocalDate;
387	import java.util.*;
388	import java.util.concurrent.atomic.AtomicLong;
389	
390	public class ReservationService {
391	
392	    private final Map<Long, Reservation> reservations;
393	    private final AtomicLong reservationIdCounter;
394	    private final RoomService roomService;
395	    private final MessageService messageService;
396	    private final DocumentService documentService;
397	
398	    public ReservationService(RoomService roomService, MessageService messageService, DocumentService documentService) {
399	        this.reservations = new HashMap<>();
400	        this.reservationIdCounter = new AtomicLong(1);
401	        this.roomService = roomService;
402	        this.messageService = messageService;
403	        this.documentService = documentService;
404	    }
405	
406	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
407	                                        String guestCpf, String companyCnpj, String companyName,
408	                                        String guestPassport, String guestCountry,
409	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
410	        Room room = roomService.getRoomByNumber(roomNumber)
411	            .orElseThrow(() -> new RoomNotFoundException());
412	
413	        if (guests < 1) {
414	            throw new InvalidRequestException("Invalid number of guests");
415	        }
416	
417	        if (guests > room.getCapacity()) {
418	            throw new CapacityExceededException();
419	        }
420	
421	        if (!checkOut.isAfter(checkIn)) {
422	            throw new InvalidRequestException("Check-out must be after check-in");
423	        }
424	
425	        if (isRoomUnavailable(roomNumber, checkIn, checkOut, null)) {
426	            throw new RoomUnavailableException();
427	        }
428	
429	        int nights = (int) checkIn.until(checkOut).getDays();
430	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
431	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
432	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
433	
434	        Long id = reservationIdCounter.getAndIncrement();
435	        Reservation reservation = new Reservation(
436	            id, roomNumber, guestName, guestEmail,
437	            guestCpf, companyCnpj, companyName, guestPassport, guestCountry,
438	            checkIn, checkOut, guests, ratePlan,
439	            nights, subtotal, discount, total
440	        );
441	
442	        reservations.put(id, reservation);
443	        return reservation;
444	    }
445	
446	    public Optional<Reservation> getReservation(Long id) {
447	        return Optional.ofNullable(reservations.get(id));
448	    }
449	
450	    public Reservation confirmReservation(Long id) {
451	        Reservation reservation = getReservation(id)
452	            .orElseThrow(() -> new ReservationNotFoundException());
453	
454	        if (reservation.getStatus() != ReservationStatus.PENDING) {
455	            throw new OperationNotAllowedException();
456	        }
457	
458	        reservation.setStatus(ReservationStatus.CONFIRMED);
459	        reservation.setAmountPaid(reservation.getTotal());
460	
461	        sendConfirmationEmail(reservation);
462	
463	        return reservation;
464	    }
465	
466	    public Reservation cancelReservation(Long id) {
467	        Reservation reservation = getReservation(id)
468	            .orElseThrow(() -> new ReservationNotFoundException());
469	
470	        if (reservation.getStatus() != ReservationStatus.PENDING &&
471	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
472	            throw new OperationNotAllowedException();
473	        }
474	
475	        BigDecimal refundAmount = BigDecimal.ZERO;
476	        if (reservation.getStatus() == ReservationStatus.CONFIRMED &&
477	            reservation.getRatePlan() == RatePlan.STANDARD) {
478	            refundAmount = reservation.getAmountPaid();
479	        }
480	
481	        reservation.setStatus(ReservationStatus.CANCELLED);
482	        reservation.setRefund(refundAmount);
483	
484	        return reservation;
485	    }
486	
487	    public Reservation checkIn(Long id) {
488	        Reservation reservation = getReservation(id)
489	            .orElseThrow(() -> new ReservationNotFoundException());
490	
491	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
492	            throw new OperationNotAllowedException();
493	        }
494	
495	        reservation.setStatus(ReservationStatus.CHECKED_IN);
496	        return reservation;
497	    }
498	
499	    public Document checkOut(Long id) {
500	        Reservation reservation = getReservation(id)
501	            .orElseThrow(() -> new ReservationNotFoundException());
502	
503	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
504	            throw new OperationNotAllowedException();
505	        }
506	
507	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
508	
509	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber()).get();
510	        return documentService.generateDocument(reservation, room);
511	    }
512	
513	    public Document getDocument(Long id) {
514	        Reservation reservation = getReservation(id)
515	            .orElseThrow(() -> new ReservationNotFoundException());
516	
517	        if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
518	            reservation.getStatus() != ReservationStatus.CHECKED_IN &&
519	            reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
520	            throw new OperationNotAllowedException();
521	        }
522	
523	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber()).get();
524	        return documentService.generateDocument(reservation, room);
525	    }
526	
527	    private void sendConfirmationEmail(Reservation reservation) {
528	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber()).get();
529	        Document document = documentService.generateDocument(reservation, room);
530	
531	        String subject = "Reserva confirmada - Pousada Maré Alta";
532	        String body = String.format(
533	            "Olá, %s!\n\n" +
534	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
535	            "%s\n\n" +
536	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
537	            "Até breve!",
538	            reservation.getGuestName(),
539	            document.getText()
540	        );
541	
542	        messageService.sendEmail(reservation.getGuestEmail(), subject, body);
543	    }
544	
545	    private boolean isRoomUnavailable(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeReservationId) {
546	        return reservations.values().stream()
547	            .filter(r -> !r.getId().equals(excludeReservationId))
548	            .filter(r -> r.getRoomNumber().equals(roomNumber))
549	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
550	            .anyMatch(r -> datesOverlap(checkIn, checkOut, r.getCheckIn(), r.getCheckOut()));
551	    }
552	
553	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
554	        return start1.isBefore(end2) && start2.isBefore(end1);
555	    }
556	
557	    public List<Reservation> getAllReservations() {
558	        return List.copyOf(reservations.values());
559	    }
560	
561	    public static class RoomNotFoundException extends RuntimeException {
562	    }
563	
564	    public static class ReservationNotFoundException extends RuntimeException {
565	    }
566	
567	    public static class InvalidRequestException extends RuntimeException {
568	        public InvalidRequestException(String message) {
569	            super(message);
570	        }
571	    }
572	
573	    public static class RoomUnavailableException extends RuntimeException {
574	    }
575	
576	    public static class CapacityExceededException extends RuntimeException {
577	    }
578	
579	    public static class OperationNotAllowedException extends RuntimeException {
580	    }
581	}

