 73	        sb.append("Hóspede: ").append(reservation.getGuestName()).append("\n");
 74	        sb.append("Quarto: ").append(room.getNumber()).append(" (").append(room.getType()).append(")\n");
 75	        sb.append("Entrada: ").append(DateFormatter.formatPtBr(reservation.getCheckIn()))
 76	          .append(" | Saída: ").append(DateFormatter.formatPtBr(reservation.getCheckOut()))
 77	          .append(" | ").append(reservation.getNights())
 78	          .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
 79	        sb.append("Diárias: ").append(MoneyFormatter.formatPtBr(reservation.getSubtotal())).append("\n");
 80	
 81	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 82	            sb.append("Desconto: ").append(MoneyFormatter.formatPtBr(reservation.getDiscount())).append("\n");
 83	        }
 84	
 85	        sb.append("Total: ").append(MoneyFormatter.formatPtBr(reservation.getTotal())).append("\n");
 86	        sb.append("ISS retido (5%): ").append(MoneyFormatter.formatPtBr(PriceCalculator.calculateIss(reservation.getTotal())));
 87	
 88	        return sb.toString();
 89	    }
 90	
 91	    private String generateBookingReceipt(Reservation reservation, Room room) {
 92	        StringBuilder sb = new StringBuilder();
 93	        sb.append("Booking receipt no. ").append(reservation.getId()).append("\n");
 94	        sb.append("Guest: ").append(reservation.getGuestName())
 95	          .append(" (passport ").append(reservation.getGuestPassport())
 96	          .append(", ").append(reservation.getGuestCountry()).append(")\n");
 97	        sb.append("Room: ").append(room.getNumber()).append(" (").append(room.getType()).append(")\n");
 98	        sb.append("Check-in: ").append(DateFormatter.formatEn(reservation.getCheckIn()))
 99	          .append(" | Check-out: ").append(DateFormatter.formatEn(reservation.getCheckOut()))
100	          .append(" | ").append(reservation.getNights())
101	          .append(reservation.getNights() == 1 ? " night" : " nights").append("\n");
102	        sb.append("Nights: ").append(MoneyFormatter.formatEn(reservation.getSubtotal())).append("\n");
103	
104	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
105	            sb.append("Discount: ").append(MoneyFormatter.formatEn(reservation.getDiscount())).append("\n");
106	        }
107	
108	        sb.append("Total: ").append(MoneyFormatter.formatEn(reservation.getTotal()));
109	
110	        return sb.toString();
111	    }
