  9	import java.time.format.DateTimeParseException;
 10	import java.util.Map;
 11	
 12	public class ApiController {
 13	
 14	    private final RoomService roomService;
 15	    private final ReservationService reservationService;
 16	    private final MessageService messageService;
 17	    private final ReportService reportService;
 18	
 19	    public ApiController(RoomService roomService, ReservationService reservationService,
 20	                        MessageService messageService, ReportService reportService) {
 21	        this.roomService = roomService;
 22	        this.reservationService = reservationService;
 23	        this.messageService = messageService;
 24	        this.reportService = reportService;
 25	    }
 26	
 27	    public void registerRoutes(Javalin app) {
 28	        app.get("/rooms", this::getRooms);
 29	        app.post("/reservations", this::createReservation);
 30	        app.get("/reservations/{id}", this::getReservation);
 31	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
 32	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
 33	        app.post("/reservations/{id}/check-in", this::checkIn);
 34	        app.post("/reservations/{id}/check-out", this::checkOut);
 35	        app.get("/reservations/{id}/document", this::getDocument);
 36	        app.get("/messages", this::getMessages);
 37	        app.get("/reports/occupancy", this::getOccupancyReport);
 38	        app.get("/reports/revenue", this::getRevenueReport);
 39	
 40	        app.exception(ReservationService.RoomNotFoundException.class, (e, ctx) -> {
 41	            ctx.status(404).json(Map.of(
 42	                "error", "ROOM_NOT_FOUND",
 43	                "message", "Room not found"
 44	            ));
 45	        });
 46	
 47	        app.exception(ReservationService.ReservationNotFoundException.class, (e, ctx) -> {
 48	            ctx.status(404).json(Map.of(
 49	                "error", "RESERVATION_NOT_FOUND",
 50	                "message", "Reservation not found"
 51	            ));
 52	        });
 53	
 54	        app.exception(ReservationService.RoomUnavailableException.class, (e, ctx) -> {
 55	            ctx.status(409).json(Map.of(
 56	                "error", "ROOM_UNAVAILABLE",
 57	                "message", "Room is not available for the selected dates"
 58	            ));
 59	        });
 60	
 61	        app.exception(ReservationService.OperationNotAllowedException.class, (e, ctx) -> {
 62	            ctx.status(409).json(Map.of(
 63	                "error", "OPERATION_NOT_ALLOWED",
 64	                "message", "Operation not allowed in current reservation status"
 65	            ));
 66	        });
 67	
 68	        app.exception(ReservationService.CapacityExceededException.class, (e, ctx) -> {
 69	            ctx.status(422).json(Map.of(
 70	                "error", "CAPACITY_EXCEEDED",
 71	                "message", "Number of guests exceeds room capacity"
 72	            ));
 73	        });
 74	
 75	        app.exception(ReservationService.InvalidRequestException.class, (e, ctx) -> {
 76	            ctx.status(400).json(Map.of(
 77	                "error", "INVALID_REQUEST",
 78	                "message", e.getMessage()
 79	            ));
 80	        });
 81	
 82	        app.exception(IllegalArgumentException.class, (e, ctx) -> {
 83	            ctx.status(400).json(Map.of(
 84	                "error", "INVALID_REQUEST",
 85	                "message", e.getMessage()
 86	            ));
 87	        });
 88	    }
 89	
 90	    private void getRooms(Context ctx) {
 91	        ctx.json(roomService.getAllRooms());
 92	    }
 93	
 94	    private void createReservation(Context ctx) {
 95	        try {
 96	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
 97	
 98	            String roomNumber = (String) body.get("roomNumber");
 99	            String guestName = (String) body.get("guestName");
100	            String guestEmail = (String) body.get("guestEmail");
101	            String checkInStr = (String) body.get("checkIn");
102	            String checkOutStr = (String) body.get("checkOut");
103	            Integer guests = body.get("guests") instanceof Integer ? (Integer) body.get("guests") : null;
104	            String ratePlanStr = (String) body.get("ratePlan");
105	
106	            String guestCpf = (String) body.get("guestCpf");
107	            String companyCnpj = (String) body.get("companyCnpj");
108	            String companyName = (String) body.get("companyName");
109	            String guestPassport = (String) body.get("guestPassport");
110	            String guestCountry = (String) body.get("guestCountry");
111	
112	            if (roomNumber == null || guestName == null || guestEmail == null ||
113	                checkInStr == null || checkOutStr == null || guests == null || ratePlanStr == null) {
114	                throw new IllegalArgumentException("Missing required fields");
115	            }
116	
117	            int identificationCount = 0;
118	            if (guestCpf != null) identificationCount++;
119	            if (companyCnpj != null && companyName != null) identificationCount++;
120	            if (guestPassport != null && guestCountry != null) identificationCount++;
121	
122	            if (identificationCount != 1) {
123	                throw new IllegalArgumentException("Invalid identification: must provide exactly one of: guestCpf, companyCnpj+companyName, or guestPassport+guestCountry");
124	            }
125	
126	            if (companyCnpj != null && companyName == null) {
127	                throw new IllegalArgumentException("companyCnpj requires companyName");
128	            }
129	            if (companyName != null && companyCnpj == null) {
130	                throw new IllegalArgumentException("companyName requires companyCnpj");
131	            }
132	            if (guestPassport != null && guestCountry == null) {
133	                throw new IllegalArgumentException("guestPassport requires guestCountry");
134	            }
135	            if (guestCountry != null && guestPassport == null) {
136	                throw new IllegalArgumentException("guestCountry requires guestPassport");
137	            }
138	
139	            var checkIn = DateFormatter.parseIso(checkInStr);
140	            var checkOut = DateFormatter.parseIso(checkOutStr);
141	            var ratePlan = RatePlan.valueOf(ratePlanStr);
142	
143	            Reservation reservation = reservationService.createReservation(
144	                roomNumber, guestName, guestEmail,
145	                guestCpf, companyCnpj, companyName, guestPassport, guestCountry,
146	                checkIn, checkOut, guests, ratePlan
147	            );
148	
149	            ctx.status(201).json(reservation);
150	        } catch (DateTimeParseException e) {
151	            throw new IllegalArgumentException("Invalid date format");
152	        }
