423	import java.math.BigDecimal;
424	import java.math.RoundingMode;
425	import java.time.LocalDate;
426	
427	public class PriceCalculator {
428	
429	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
430	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
431	
432	    public static boolean isHighSeason(LocalDate date) {
433	        int month = date.getMonthValue();
434	        int day = date.getDayOfMonth();
435	
436	        if (month == 7) {
437	            return true;
438	        }
439	
440	        if (month == 12 && day >= 15) {
441	            return true;
442	        }
443	
444	        if (month == 1 || month == 2) {
445	            return true;
446	        }
447	
448	        return false;
449	    }
450	
451	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate date) {
452	        BigDecimal price = baseRate;
453	        if (isHighSeason(date)) {
454	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
455	        }
456	        return round(price);
457	    }
458	
459	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
460	        BigDecimal subtotal = BigDecimal.ZERO;
461	        LocalDate current = checkIn;
462	
463	        while (current.isBefore(checkOut)) {
464	            BigDecimal nightPrice = calculateNightPrice(baseRate, current);
465	            subtotal = subtotal.add(nightPrice);
466	            current = current.plusDays(1);
467	        }
468	
469	        return round(subtotal);
470	    }
471	
472	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
473	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
474	            return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
475	        }
476	        return BigDecimal.ZERO;
477	    }
478	
479	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
480	        return round(subtotal.subtract(discount));
481	    }
482	
483	    public static BigDecimal calculateIss(BigDecimal total) {
484	        return round(total.multiply(new BigDecimal("0.05")));
485	    }
486	
487	    public static BigDecimal round(BigDecimal value) {
488	        return value.setScale(2, RoundingMode.HALF_EVEN);
489	    }
490	}
